    return '?';
}

lessons.solution:
static char firstUnique(String s) {
    java.util.HashMap<Character,Integer> counts=new java.util.HashMap<>();
    for(int i=0;i<s.length();i++) {
        char ch=s.charAt(i);
        counts.put(ch,counts.getOrDefault(ch,0)+1);
    }
    for(int i=0;i<s.length();i++) {
        char ch=s.charAt(i);
        if(counts.get(ch)==1)return ch;
    }
    return '?';
}

