lessons.starter:
static boolean binaryContains(int[] values,int target) {
    return false;
}

lessons.solution:
static boolean binaryContains(int[] values,int target) {
    int low=0,high=values.length-1;
    while(low<=high) {
        int mid=low+(high-low)/2;
        if(values[mid]==target)return true;
        if(values[mid]<target)low=mid+1;
        else high=mid-1;
    }
    return false;
}

lessons.starter:
static boolean balanced(String s) {
    return false;
}

lessons.solution:
static boolean balanced(String s) {
    int depth=0;
    for(int i=0;i<s.length();i++) {
        if(s.charAt(i)=='(')depth++;
        else depth--;
        if(depth<0)return false;
    }
    return depth==0;
}
